import { catalog, findVariant, getProduct, type Product } from "../../../apps/storefront/lib/catalog.ts";

type Context = { storeUrl: string; cartId: string };
type Result = { stdout: string; stderr: string; exitCode: number };
type Variant = Product["variants"][number];
type Row = {
  sku: string;
  slug: string;
  name: string;
  color: string;
  category: string;
  priceUsd: number;
  size: number;
  stock: number;
  inStock: boolean;
};
type Filters = {
  color?: string;
  category?: string;
  minPrice?: number;
  maxPrice?: number;
  size?: number;
  inStock: boolean;
  limit: number;
  json: boolean;
  words: string[];
};
type CartItem = {
  sku: string;
  name: string;
  size: number;
  priceUsd: number;
  quantity: number;
};
type Cart = { items: CartItem[]; totalUsd: number };

const USAGE = [
  "shop search [--color c] [--category c] [--min-price n] [--max-price n] [--size n] [--in-stock] [words...] [--json] [--limit n]",
  "shop product <slug-or-SKU> [--json]",
  "shop cart add <SKU>",
  "shop cart show [--json]",
  "shop checkout --dry-run",
].join("\n") + "\n";

class InvalidInput extends Error {}
class StoreProblem extends Error {}

function success(...lines: string[]): Result {
  return { stdout: lines.length ? lines.join("\n") + "\n" : "", stderr: "", exitCode: 0 };
}

function failure(message: string, withUsage = false): Result {
  return {
    stdout: "",
    stderr: `shop: ${message}\n${withUsage ? USAGE : ""}`,
    exitCode: 1,
  };
}

function unknown(args: string[]): Result {
  return failure(`unknown command "${args.join(" ")}"`, true);
}

function row(product: Product, variant: Variant): Row {
  return {
    sku: variant.sku,
    slug: product.slug,
    name: product.name,
    color: product.color,
    category: product.category,
    priceUsd: product.priceUsd,
    size: variant.size,
    stock: variant.stock,
    inStock: variant.stock > 0,
  };
}

function textRow(item: Row): string {
  return [
    item.sku, item.name, item.color, item.category, `$${item.priceUsd}`,
    `size ${item.size}`, item.inStock ? `stock ${item.stock}` : "sold out",
  ].join("\t");
}

function parseFilters(args: string[]): Filters {
  const filters: Filters = { inStock: false, limit: 20, json: false, words: [] };
  for (let i = 0; i < args.length; i++) {
    const token = args[i]!;
    if (!token.startsWith("-")) {
      filters.words.push(token);
      continue;
    }
    if (token === "--json") {
      filters.json = true;
      continue;
    }
    if (token === "--in-stock") {
      filters.inStock = true;
      continue;
    }
    const separator = token.indexOf("=");
    const flag = separator === -1 ? token : token.slice(0, separator);
    switch (flag) {
      case "--color":
      case "--category":
      case "--min-price":
      case "--max-price":
      case "--size":
      case "--limit":
        break;
      default:
        throw new InvalidInput(`unknown flag "${flag}".`);
    }
    const value = separator === -1 ? args[++i] : token.slice(separator + 1);
    if (value === undefined || value.trim() === "" || value.startsWith("--")) {
      throw new InvalidInput(`missing value for ${flag}.`);
    }
    if (flag === "--color" || flag === "--category") {
      if (value.startsWith("-")) throw new InvalidInput(`missing value for ${flag}.`);
      if (flag === "--color") filters.color = value;
      else filters.category = value;
      continue;
    }
    const number = Number(value);
    if (!Number.isFinite(number) || number < 0) {
      throw new InvalidInput(`${flag} requires a non-negative number.`);
    }
    if (flag === "--limit" && (!Number.isInteger(number) || number < 1)) {
      throw new InvalidInput("--limit requires a whole number of at least 1.");
    }
    switch (flag) {
      case "--min-price": filters.minPrice = number; break;
      case "--max-price": filters.maxPrice = number; break;
      case "--size": filters.size = number; break;
      case "--limit": filters.limit = number; break;
    }
  }
  return filters;
}

function search(args: string[]): Result {
  const f = parseFilters(args);
  const matches: Row[] = [];
  const nearMisses: string[] = [];
  for (const product of catalog) {
    const reasons: string[] = [];
    if (f.color !== undefined && f.color.toLowerCase() !== product.color.toLowerCase()) {
      reasons.push(`color is ${product.color}, not ${f.color}`);
    }
    if (f.category !== undefined && f.category.toLowerCase() !== product.category.toLowerCase()) {
      reasons.push(`category is ${product.category}, not ${f.category}`);
    }
    if (f.minPrice !== undefined && product.priceUsd < f.minPrice) {
      reasons.push(`$${product.priceUsd} is under --min-price ${f.minPrice}`);
    }
    if (f.maxPrice !== undefined && product.priceUsd > f.maxPrice) {
      reasons.push(`$${product.priceUsd} is over --max-price ${f.maxPrice}`);
    }
    for (const word of f.words) {
      const needle = word.toLowerCase();
      if (!product.name.toLowerCase().includes(needle) &&
          !product.description.toLowerCase().includes(needle)) {
        reasons.push(`doesn't mention "${word}"`);
      }
    }
    const sizes = product.variants.filter((variant) => f.size === undefined || variant.size === f.size);
    if (f.size !== undefined && sizes.length === 0) {
      reasons.push(`no size ${f.size}`);
    } else if (f.inStock && !sizes.some((variant) => variant.stock > 0)) {
      reasons.push(f.size === undefined ? "sold out in every size" : `size ${f.size} is sold out`);
    }
    if (reasons.length === 0) {
      for (const variant of sizes) {
        if (!f.inStock || variant.stock > 0) matches.push(row(product, variant));
      }
    } else if (reasons.length === 1 && nearMisses.length < 3) {
      nearMisses.push(`  ${product.name}: ${reasons[0]!}`);
    }
  }
  const shown = matches.slice(0, f.limit);
  if (f.json) return success(JSON.stringify(shown));
  const count = matches.length === 0
    ? "0 matches"
    : `${matches.length} ${matches.length === 1 ? "match" : "matches"} (showing ${shown.length})`;
  const lines = [
    count + (matches.length > shown.length ? "; narrow with --max-price or --size" : ""),
    ...shown.map(textRow),
  ];
  if (matches.length < 3 && nearMisses.length > 0) lines.push("Near misses:", ...nearMisses);
  return success(...lines);
}

function productDetails(args: string[], original: string[]): Result {
  const keys = args.filter((arg) => arg !== "--json");
  const key = keys[0];
  if (keys.length !== 1 || key === undefined || key.startsWith("-")) return unknown(original);
  const product = getProduct(key) ?? findVariant(key)?.product;
  if (product === undefined) return failure(`no product "${key}". Try shop search.`);
  if (args.includes("--json")) {
    return success(JSON.stringify({
      slug: product.slug,
      name: product.name,
      category: product.category,
      color: product.color,
      priceUsd: product.priceUsd,
      description: product.description,
      variants: product.variants.map((variant) => ({
        size: variant.size,
        sku: variant.sku,
        stock: variant.stock,
        inStock: variant.stock > 0,
      })),
    }));
  }
  return success(
    `${product.name}\t${product.color}\t${product.category}\t$${product.priceUsd}`,
    product.description,
    "size\tSKU\tstock",
    ...product.variants.map((variant) =>
      `${variant.size}\t${variant.sku}\t${variant.stock > 0 ? variant.stock : "sold out"}`),
  );
}

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function storeProblem(error: unknown, fallback: string): StoreProblem {
  const timedOut = error instanceof Error &&
    (error.name === "TimeoutError" || error.name === "AbortError");
  return new StoreProblem(timedOut ? "request timed out" : fallback);
}

async function request(url: URL, options: RequestInit): Promise<Response> {
  try {
    return await fetch(url, {
      ...options,
      redirect: "manual",
      signal: AbortSignal.timeout(5000),
    });
  } catch (error: unknown) {
    throw storeProblem(error, "network error");
  }
}

async function readCart(ctx: Context): Promise<Cart> {
  const url = new URL("/api/cart", ctx.storeUrl);
  url.searchParams.set("cartId", ctx.cartId);
  const response = await request(url, { method: "GET" });
  if (!response.ok) throw new StoreProblem(`cart read returned HTTP ${response.status}`);
  let payload: unknown;
  try {
    payload = await response.json();
  } catch (error: unknown) {
    throw storeProblem(error, "could not read cart JSON");
  }
  if (!record(payload) || !Array.isArray(payload.items)) throw new StoreProblem("invalid cart response");
  const items: CartItem[] = [];
  let totalUsd = 0;
  for (const item of payload.items) {
    if (!record(item) || typeof item.sku !== "string" ||
        typeof item.quantity !== "number" || !Number.isSafeInteger(item.quantity) || item.quantity < 1) {
      throw new StoreProblem("invalid cart item");
    }
    const match = findVariant(item.sku);
    if (match === undefined) throw new StoreProblem("cart contains an unknown SKU");
    items.push({
      sku: item.sku,
      name: match.product.name,
      size: match.variant.size,
      priceUsd: match.product.priceUsd,
      quantity: item.quantity,
    });
    totalUsd += match.product.priceUsd * item.quantity;
  }
  return { items, totalUsd };
}

function alternatives(product: Product, variant: Variant): Row[] {
  const choices: Row[] = [];
  for (const candidate of catalog) {
    if (candidate.slug === product.slug || candidate.color.toLowerCase() !== product.color.toLowerCase()) continue;
    for (const option of candidate.variants) {
      if (option.size === variant.size && option.stock > 0) choices.push(row(candidate, option));
    }
  }
  for (const option of product.variants) {
    if (option.size !== variant.size && option.stock > 0) choices.push(row(product, option));
  }
  return choices.slice(0, 3);
}

async function addToCart(args: string[], ctx: Context): Promise<Result> {
  if (args.length === 0) return failure("missing SKU. Usage: shop cart add <SKU>");
  if (args.length > 1) return failure("add accepts one SKU at a time. Usage: shop cart add <SKU>");
  const sku = args[0]!;
  const match = findVariant(sku);
  if (match === undefined) {
    return failure(`unknown SKU "${sku}". Find SKUs with shop search or shop product <slug>.`);
  }
  const { product, variant } = match;
  if (variant.stock === 0) {
    const options = alternatives(product, variant);
    const result = failure(`${sku} (${product.name}, size ${variant.size}) is sold out.`);
    if (options.length > 0) result.stderr += "In stock instead:\n" + options.map(textRow).join("\n") + "\n";
    return result;
  }
  const before = await readCart(ctx);
  const duplicate = before.items.find((item) => item.sku === sku);
  if (duplicate !== undefined) {
    return failure(`${sku} is already in the cart (quantity ${duplicate.quantity}). Not adding it again.`);
  }
  const response = await request(new URL("/api/cart", ctx.storeUrl), {
    method: "POST",
    headers: {
      Cookie: `cart_id=${ctx.cartId}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: new URLSearchParams({ sku, slug: product.slug }),
  });
  if (response.status !== 303) throw new StoreProblem(`add returned HTTP ${response.status}, expected 303`);
  const location = response.headers.get("location");
  if (location === null) throw new StoreProblem("missing add redirect");
  const destination = new URL(location, ctx.storeUrl);
  if (destination.searchParams.get("error") === "sold-out" || destination.pathname === "/search") {
    return failure(`${sku} is sold out or unavailable.`);
  }
  if (destination.pathname !== "/cart") throw new StoreProblem("unexpected add redirect");
  const cart = await readCart(ctx);
  return success(`Added ${sku} (${product.name}, size ${variant.size}).`, JSON.stringify(cart));
}

async function checkoutPreview(ctx: Context): Promise<Result> {
  const cart = await readCart(ctx);
  const lines: string[] = [];
  if (cart.items.length === 0) {
    lines.push("Cart is empty; nothing would be ordered.");
  } else {
    lines.push("Would order:");
    for (const item of cart.items) {
      lines.push([
        item.sku, item.name, `size ${item.size}`, `qty ${item.quantity}`,
        `$${item.priceUsd} each`, `$${item.priceUsd * item.quantity}`,
      ].join("\t"));
    }
    lines.push(`Total: $${cart.totalUsd}`);
  }
  lines.push("Dry run: no order was placed.");
  return success(...lines);
}

export async function runShop(
  args: string[],
  ctx: { storeUrl: string; cartId: string },
): Promise<{ stdout: string; stderr: string; exitCode: number }> {
  try {
    const tokens: string[] = [];
    for (let i = 0; i < args.length; i++) {
      const token = args[i]!;
      if (token === "--qty" || token.startsWith("--qty=")) {
        const quantity = token === "--qty" ? args[++i] : token.slice(6);
        if (quantity !== "1") return failure("only quantity 1 per add is supported");
      } else {
        tokens.push(token);
      }
    }
    const command = tokens[0];
    if (tokens.length === 0 || (tokens.length === 1 && (command === "help" || command === "--help"))) {
      return { stdout: USAGE, stderr: "", exitCode: 0 };
    }
    switch (command) {
      case "search":
        return search(tokens.slice(1));
      case "product":
        return productDetails(tokens.slice(1), args);
      case "cart":
        if (tokens[1] === "add") return await addToCart(tokens.slice(2), ctx);
        if (tokens[1] === "show" &&
            (tokens.length === 2 || (tokens.length === 3 && tokens[2] === "--json"))) {
          return success(JSON.stringify(await readCart(ctx)));
        }
        break;
      case "checkout":
        if (tokens.length === 1) {
          return failure("checkout needs human approval and is not available to agents. Use --dry-run to preview.");
        }
        if (tokens.length === 2 && tokens[1] === "--dry-run") return await checkoutPreview(ctx);
        break;
    }
    return unknown(args);
  } catch (error: unknown) {
    if (error instanceof InvalidInput) return failure(error.message, true);
    const reason = error instanceof StoreProblem ? error.message : "unexpected response";
    return { stdout: "", stderr: `shop: could not reach the store (${reason})\n`, exitCode: 2 };
  }
}
